Certainly! Below is an example of how you might implement a Contextual Multi-Armed Bandit (CMAB) algorithm using object-oriented programming (OOP) in Python. This implementation will sample actions based on three different models.

```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.lstsq(X, y, rcond=None)[0]

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def __init__(self):
        super().__init__()

    def fit(self, X, y):
        pass

    def predict(self, X):
        return np.random.rand(len(X))

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.rewards = {model: [] for model in models}
        self.contexts = []
        self.actions = []

    def select_action(self, context):
        if np.random.rand() < self.epsilon:
            action = np.random.choice(len(self.models))
        else:
            predictions = [model.predict([context])[0] for model in self.models]
            action = np.argmax(predictions)

        self.contexts.append(context)
        self.actions.append(action)
        return action

    def update(self, action, reward):
        self.rewards[self.models[action]].append(reward)

# Example usage
if __name__ == "__main__":
    # Generate some synthetic data
    n_samples = 1000
    n_features = 5
    contexts = np.random.randn(n_samples, n_features)
    true_rewards = np.dot(contexts, np.array([1, -2, 3, -4, 5])) + np.random.randn(n_samples) * 0.1

    # Initialize models
    models = [LinearModel(), RandomModel()]

    # Create and train the bandit
    bandit = EpsilonGreedyBandit(models)
    for i in range(n_samples):
        action = bandit.select_action(contexts[i])
        reward = true_rewards[i]
        bandit.update(action, reward)

    # Print results
    print("Rewards per model:")
    for model, rewards in bandit.rewards.items():
        print(f"Model: {model.__class__.__name__}, Mean Reward: {np.mean(rewards)}")
```

### Explanation:
1. **Model Class**: A base class for all models. It has methods `fit` and `predict`.
2. **LinearModel Class**: Implements a simple linear regression model.
3. **RandomModel Class**: Always returns random predictions.
4. **EpsilonGreedyBandit Class**: Manages the selection of actions and updating of rewards. It uses the epsilon-greedy strategy to balance exploration and exploitation.
5. **Example Usage**: Generates synthetic data, initializes the bandit with two models, and runs the simulation.

This code provides a basic framework for implementing a CMAB algorithm. You can extend it by adding more sophisticated models or strategies as needed.

