class Program
{
    static void Main()
    {
        // Calculate pi using the Leibniz formula
        double pi = 0;
        int iterations = 1000000; // Increase this value for more accurate results

        for (int i = 0; i < iterations; i++)
        {
            pi += Math.Pow(-1, i) / (2 * i + 1);
        }

        pi *= 4;

        // Round pi to 5 decimal places
        pi = Math.Round(pi, 5);

        // Perform two XOR operations on the result
        byte[] bytes = BitConverter.GetBytes(pi);
        Array.Reverse(bytes); // Reverse the byte order to match the expected format
        uint xorResult = BitConverter.ToUInt32(bytes, 0);

        xorResult ^= 0x12345678; // First XOR operation
        xorResult ^= 0x9ABCDEF0; // Second XOR operation

        Console.WriteLine("Pi rounded to 5 decimal places: " + pi);
        Console.WriteLine("XOR result after two operations: " + xorResult.ToString("X"));
    }
}
```

