```javascript
document.addEventListener('DOMContentLoaded', function() {
    const circle = document.getElementById('circle');
    const marker = document.getElementById('marker');

    let startX, startY;

    // Handle touchstart event
    circle.addEventListener('touchstart', (e) => {
        e.preventDefault();
        startX = e.touches[0].clientX - circle.offsetLeft;
        startY = e.touches[0].clientY - circle.offsetTop;
    });

    // Handle touchmove event
    circle.addEventListener('touchmove', (e) => {
        e.preventDefault();
        const x = e.touches[0].clientX - circle.offsetLeft;
        const y = e.touches[0].clientY - circle.offsetTop;

        const dx = x - startX;
        const dy = y - startY;

        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance > 100) return; // Limit maximum distance

        const angle = Math.atan2(dy, dx);
        const radius = 150; // Maximum radius

        const newRadius = Math.min(radius, distance);

        const newX = startX + newRadius * Math.cos(angle);
        const newY = startY + newRadius * Math.sin(angle);

        circle.style.left = `${newX}px`;
        circle.style.top = `${newY}px`;

        marker.style.left = `${newX}px`;
        marker.style.top = `${newY}px`;
    });
});
```

