```javascript
function fibonacciModulo(n, p) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  let prev = 0;
  let curr = 1;

  for (let i = 2; i <= n; i++) {
    const next = (prev + curr) % p;
    prev = curr;
    curr = next;
  }

  return curr;
}

