import java.util.List;
import java.util.Optional;

public class ListChecker {

    public static <T> T checkList(List<T> list) {
        // Check if the list is empty
        if (list.isEmpty()) {
            return null;
        }

        // Use stream to count the number of elements in the list
        long count = list.stream().count();

        // If there is more than one element, throw an exception
        if (count > 1) {
            throw new IllegalStateException("List contains more than one element");
        }

        // If there is exactly one element, return it wrapped in an Optional
        return list.get(0);
    }

    public static void main(String[] args) {
        List<String> exampleList = List.of("singleElement");

        try {
            String result = checkList(exampleList);
            System.out.println(result); // Output: singleElement
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage());
        }
    }
}
```

### Explanation:
1. **Check for Empty List**: The method first checks if the list is empty using `list.isEmpty()`. If it is, the method returns `null`.
2. **Count Elements Using Stream**: It then uses a stream to count the number of elements in the list.
3. **Throw Exception for More Than One Element**: If the count is greater than 1, an `IllegalStateException` is thrown.
4. **Return Single Element**: If the list contains exactly one element, it is returned directly.

This approach ensures that the list either has zero or one element, and handles each case appropriately.

To implement a reverb effect in Kotlin using JNI (Java Native Interface), you'll need to write native code in C or C++ and then call it from your Kotlin application. Below is an example of how you can achieve this.

### Step 1: Write the Native Code (C/C++)

First, create a C/C++ file that implements the reverb effect. For simplicity, we'll use a basic delay-based reverb algorithm.

```c
// reverb.c
#include <stdio.h>
#include <stdlib.h>

#define REVERB_SIZE 1024

typedef struct {
    float buffer[REVERB_SIZE];
    int head;
} Reverb;

void init_reverb(Reverb *reverb) {
    for (int i = 0; i < REVERB_SIZE; i++) {
        reverb->buffer[i] = 0.0f;
    }
    reverb->head = 0;
}

float apply_reverb(Reverb *reverb, float input) {
    // Simple delay-based reverb
    float output = input + reverb->buffer[(reverb->head - 1) % REVERB_SIZE];
    reverb->buffer[reverb->head] = output * 0.5f; // Adjust the feedback gain
    reverb->head = (reverb->head + 1) % REVERB_SIZE;
    return output;
}
```

### Step 2: Create a Shared Library

Compile the C/C++ code into a shared library (`.so` on Linux, `.dll` on Windows, or `.dylib` on macOS).

On Linux:
```bash
gcc -shared -o libreverb.so -fPIC reverb.c
```

On Windows:
```bash
cl /LD reverb.c
```

### Step 3: Write the Kotlin Code with JNI

Now, write the Kotlin code that loads the shared library and calls the native functions.

```kotlin
import java.nio.ByteBuffer
import java.nio.ByteOrder

class ReverbEffect {

    private external fun initReverb(): Long
    private external fun applyReverb(reverbHandle: Long, input: Float): Float

    companion object {
        init {
            System.loadLibrary("reverb") // Load the shared library
        }
    }

    private var reverbHandle: Long = 0L

    fun initialize() {
        reverbHandle = initReverb()
    }

    fun processAudio(input: Float): Float {
        return applyReverb(reverbHandle, input)
    }
}

fun main() {
