### Step 1: Set Up Pinia Store

```javascript
// stores/sessionStore.js
import { defineStore } from 'pinia';

export const useSessionStore = defineStore('session', {
  state: () => ({
    user: null,
    sessionData: {},
  }),
  actions: {
    async fetchSession() {
      // This action will be called when we need to fetch new data
    },
  },
});
```

### Step 2: Create a Query Function

```javascript
// composable/useFetchSession.js
import { useQuery } from '@tanstack/vue-query';
import axios from 'axios';
import { useSessionStore } from './stores/sessionStore';

const useFetchSession = () => {
  const sessionStore = useSessionStore();

  return useQuery(
    ['session'],
    async () => {
      const response = await axios.get('/get_session');
      return response.data;
    },
    {
      onSuccess: (data) => {
        // Update the Pinia store with the selected keys
        sessionStore.user = data.user; // Assuming 'user' is one of the keys
        sessionStore.sessionData = { ...sessionStore.sessionData, ...data };
      },
    }
  );
};

export default useFetchSession;
```

### Step 3: Use the Composable in Your Component

```vue
